mapper.select:
SELECT 
FROM feature_flag
WHERE tenant_id = #{tenantId}
  AND flag_key = #{flagKey}
  AND is_deleted = 0
LIMIT 1

mapper.update:
UPDATE feature_flag
SET enabled = #{enabled},
    config_json = #{configJson},
    gmt_modified = #{gmtModified}
WHERE tenant_id = #{tenantId}
  AND flag_key = #{flagKey}
  AND is_deleted = 0
